     "시각 뒤에 에를 붙여요. 시는 고유어, 분은 한자어예요.",
     "한 시, 두 시, 세 시. 오 분, 십 분, 삼십 분.",
     "한 시, 두 시, 세 시. 오 분, 십 분, 삼십 분.",
